def choose_move(observation):
    def p(v, d=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return d

    def sl(v):
        return v if isinstance(v, (list, tuple)) else []

    def mode_hint(obs):
        keys = ("game_mode", "mode", "objective", "task", "role", "agent_role", "play_mode")
        s = ""
        for k in keys:
            v = obs.get(k, "")
            if isinstance(v, str):
                s += " " + v.lower()
        return s

    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    sx, sy = p(observation.get("self_position", (0, 0)), (0, 0))
    ox, oy = p(observation.get("opponent_position", (sx, sy)), (sx, sy))

    obs = set()
    for a in sl(observation.get("obstacles", [])):
        q = p(a)
        if q is not None:
            obs.add(q)

    resources = []
    for a in sl(observation.get("resources", [])):
        q = p(a)
        if q is not None:
            resources.append(q)

    own = set()
    for k in ("territory", "owned_cells", "claimed_cells", "my_cells", "self_territory"):
        for a in sl(observation.get(k, [])):
            q = p(a)
            if q is not None:
                own.add(q)

    path = []
    for a in sl(observation.get("self_path", [])):
        q = p(a)
        if q is not None:
            path.append(q)

    if not resources:
        for q in path:
            if q not in resources:
                resources.append(q)

    hint = mode_hint(observation)
    flee = ("evad" in hint) or ("flee" in hint) or ("avoid" in hint)
    chase = ("pursu" in hint) or ("chase" in hint) or ("hunt" in hint) or ("attack" in hint)

    cands = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    best = (0, 0)
    best_score = -10**18

    center_x = (w - 1) / 2 if w else 0
    center_y = (h - 1) / 2 if h else 0

    for dx, dy in cands:
        nx, ny = sx + dx, sy + dy
        if (nx, ny) in obs:
            continue
        if w and (nx < 0 or nx >= w):
            continue
        if h and (ny < 0 or ny >= h):
            continue

        score = 0

        # Mobility / safety.
        free_n = 0
        for ax, ay in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            xx, yy = nx + ax, ny + ay
            if (xx, yy) not in obs and (not w or 0 <= xx < w) and (not h or 0 <= yy < h):
                free_n += 1
        score += free_n * 7

        # Resource seeking.
        if resources:
            md = 10**9
            tx, ty = resources[0]
            for rx, ry in resources:
                d = abs(rx - nx) + abs(ry - ny)
                if d < md or (d == md and (rx, ry) < (tx, ty)):
                    md = d
                    tx, ty = rx, ry
            score += (20 - md) * 12
            if (nx, ny) in own:
                score -= 3
        else:
            # Territorial expansion / exploration.
            if own and (nx, ny) not in own:
                score += 8
            if own:
                adj = 0
                for ax, ay in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    if (nx + ax, ny + ay) in own:
                        adj += 1
                score += adj * 5

            # Center bias when not explicitly pursuing/evading.
            if not chase and not flee and w and h:
                score += int((w + h) - (abs(nx - center_x) + abs(ny - center_y)) * 2)

        # Opponent interaction.
        od = abs(nx - ox) + abs(ny - oy)
        if flee:
            score += od * 10
        elif chase:
            score += (20 - od) * 10
        else:
            if od <= 2:
                score += od * 4
            else:
                score -= max(0, 6 - od) * 2

        # Mild preference to keep moving if good.
        if (dx, dy) != (0, 0):
            score += 1

        if score > best_score or (score == best_score and (dx, dy) < best):
            best_score = score
            best = (dx, dy)

    return [best[0], best[1]]

